<?php
namespace Dth\Crm\Services;
use Dth\Crm\Enums\QualificationStatus; use Dth\Crm\Models\ContactQualification; use Dth\Crm\Contracts\SalesHandoffProvider; use Dth\Crm\DTO\QualifiedLeadData; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
final class QualificationService {private const T=['new'=>['assigned','duplicate','spam','archived'],'assigned'=>['contacting','duplicate','spam','archived'],'contacting'=>['follow_up','qualified','unqualified','duplicate','spam'],'follow_up'=>['contacting','qualified','unqualified','duplicate','spam','archived'],'qualified'=>['converted','unqualified'],'unqualified'=>['archived'],'duplicate'=>['archived'],'spam'=>['archived'],'converted'=>[],'archived'=>[]];public function __construct(private SalesHandoffProvider $sales){}
 public function transition(ContactQualification $q,string $to,array $data=[]):ContactQualification{return DB::transaction(function()use($q,$to,$data){$q=ContactQualification::with('lead')->lockForUpdate()->findOrFail($q->id);$from=$q->status;if(!in_array($to,self::T[$from]??[],true))throw ValidationException::withMessages(['status'=>"Không thể chuyển từ {$from} sang {$to}."]);if($to==='follow_up'&&empty($data['next_follow_up_at']))throw ValidationException::withMessages(['next_follow_up_at'=>'Bắt buộc chọn thời gian theo dõi.']);if($to==='qualified'){if(empty($data['service_interest']??$q->service_interest))throw ValidationException::withMessages(['service_interest'=>'Dịch vụ quan tâm là bắt buộc.']);$budget=$data['budget_status']??$q->budget_status;if(!in_array($budget,['confirmed','estimated','unknown'],true))throw ValidationException::withMessages(['budget_status'=>'Vui lòng chọn tình trạng ngân sách hợp lệ.']);$timeline=$data['purchase_timeline']??$q->purchase_timeline;if(!in_array($timeline,['immediate','within_1_month','within_3_months','within_6_months','later','unknown'],true))throw ValidationException::withMessages(['purchase_timeline'=>'Vui lòng xác định thời gian dự kiến mua.']);if(isset($data['budget_amount'])&&$data['budget_amount']!==null&&(!is_numeric($data['budget_amount'])||(float)$data['budget_amount']<0))throw ValidationException::withMessages(['budget_amount'=>'Ngân sách phải là số không âm.']);}$payload=array_merge($data,['status'=>$to]);if($to==='qualified')$payload['qualified_at']=now();if($to==='converted')$payload['converted_at']=now();$q->update($payload);$lead=$q->lead;if($to==='duplicate'||$to==='spam')$lead->update(['intake_status'=>$to]);elseif($to==='unqualified'||$to==='archived')$lead->update(['intake_status'=>'closed']);elseif(in_array($to,['assigned','contacting','follow_up','qualified'],true))$lead->update(['intake_status'=>'active']);if($to==='qualified'&&$this->sales->available()){$ref=$this->sales->handoff(new QualifiedLeadData((string)$lead->id,$lead->lead_code,(string)$lead->contact_id,(string)$lead->company_id,$lead->service_reference,$lead->estimated_value,['qualification_id'=>$q->id]));if($ref)$lead->update(['sales_opportunity_reference'=>$ref,'converted_to_opportunity_at'=>now(),'intake_status'=>'converted_to_opportunity']);}return $q->fresh();});}
}
